// libycxx core: text_encoding ([text.encoding]) -- everything but environment(), which asks the
// OS and is defined in the hosted runtime (src/hosted/text_encoding.cpp).
//
// The registry is ycxx/core/text_encoding_table.hpp, generated by tools/gen_text_encoding.py
// from the IANA Character Sets registry: te_names lists every known registered encoding's
// primary name and aliases grouped by MIBenum (the primary name first), te_keys the comp-name
// canonical form of every name, sorted, for the binary search of text_encoding(string_view).
// comp-name ([text.encoding.members]/19) assumes an ASCII-compatible ordinary literal encoding.
#pragma once

#include <ycxx/core/climits.hpp>
#include <ycxx/core/cstddef.hpp>
#include <ycxx/core/cstdint.hpp>
